"""Supplementary visual transcription, generated independently of the original 12 pages.
Every listed page was visually inspected. Run to reproduce supplemental JSON only.
No external OCR/model calls. Immutable PDF preserved. Coordinates are approximate.
"""
from pathlib import Path
import json, hashlib
ROOT=Path(__file__).resolve().parent
manifest=json.loads((ROOT/'data/source-manifest.json').read_text())
assert hashlib.sha256((ROOT/'source/original.pdf').read_bytes()).hexdigest()==manifest['source_sha256']
PAGES=[]
def page(n,title,summary,tags,notes=None,brand=True):
 p={'page_number':n,'page_id':manifest['pages'][n-1]['page_id'],'source_sha256':manifest['source_sha256'],'revision':1,'title':title,'kind':'视觉转录','summary':{'text':summary,'origin':'AI summary of this page only'},'tags':tags,'reading_status':'Codex visual transcription; human review pending','issues':notes or [],'elements':[],'additional_visible_text':[],'html_editability':'native','reference':{'pdf':'source/original.pdf','page':n,'image':f'images/page-{n:03}.jpg'},'provenance':{'bbox_kind':'manual approximate page region; not word-level OCR','method':'current Codex subagent visual reading','model_id':'not independently observable','external_model_api_calls':0},'layout_mode':'approximate source reconstruction; human review pending'}
 PAGES.append(p)
 if brand:image(p,[1685,70,158,58],xref=21,label='造物云',role='brand')
 return p

def add(p,typ,box,**kw):
 e={'id':f'p{p["page_number"]:03}-b{len(p["elements"])+1:03}','type':typ,'box':box,**kw};p['elements'].append(e);return e

def text(p,s,x,y,w,h,size=40,bold=False,color='#141414',align='left',font='serif'):return add(p,'text',[x,y,w,h],text=s,font_size=size,bold=bold,color=color,align=align,font=font,origin='source_visual_transcription')
def image(p,box,clip=None,xref=None,label='',role='source_visual'):
 if role!='brand' and role!='reference':p['html_editability']='mixed'
 return add(p,'image',box,xref=xref,clip=clip,alt=label,role=role,editable=False)
def crop(p,x,y,w,h,label='',role='source_visual'):return image(p,[x,y,w,h],clip=[x,y,x+w,y+h],label=label,role=role)
def rect(p,x,y,w,h,fill='#fff',stroke=None,r=0):return add(p,'rect',[x,y,w,h],fill=fill,stroke=stroke,radius=r)
def line(p,x1,y1,x2,y2,color='#777',width=2,arrow=False,dash=False):return add(p,'line',[min(x1,x2),min(y1,y2),max(abs(x2-x1),1),max(abs(y2-y1),1)],points=[x1,y1,x2,y2],color=color,width=width,arrow=arrow,dash=dash)
def title(p,size=62):text(p,p['title'],110,100,1540,120,size,True)
def table(p,box,headers,rows,size=25):return add(p,'table',box,headers=headers,rows=rows,font_size=size,column_widths=[100/len(headers)]*len(headers),style='plain')
def labels(p,*s):p['additional_visible_text'].extend(s)
def qr(p,x,y,w=145):crop(p,x,y,w,w,'原页参考二维码','reference')

